function renderCatalog(){let list=DZ.products().filter(p=>p.enabled!==false&&p.variants.some(v=>v.enabled!==false));if(category!=='all')list=list.filter(p=>p.category===category);if(query)list=list.filter(p=>(p.title+' '+p.description+' '+categoryName(p.category)).toLocaleLowerCase('fa').includes(query.toLocaleLowerCase('fa')));if(favoritesOnly)list=list.filter(p=>favorites.includes(p.id));const basePrice=p=>Math.min(...p.variants.filter(v=>v.enabled!==false).map(v=>DZ.price(p,v)));if(sort==='low')list.sort((a,b)=>basePrice(a)-basePrice(b));if(sort==='high')list.sort((a,b)=>basePrice(b)-basePrice(a));if(sort==='stock')list.sort((a,b)=>Number(b.variants.some(v=>DZ.stockAvailable(b.id,v.id)>0))-Number(a.variants.some(v=>DZ.stockAvailable(a.id,v.id)>0)));$('catalogFilters').innerHTML=cats.map(c=>`<button class="filter-btn ${category===c[0]?'active':''}" data-action="filter" data-category="${c[0]}" aria-pressed="${category===c[0]}">${c[1]}</button>`).join('');const display=showAll?list:list.slice(0,8);$('showMoreBtn').hidden=list.length<=8||showAll;$('catalogTitle').textContent=favoritesOnly?'انتخاب‌های محبوب تو':category==='all'?'منتخب دژاوو':categoryName(category);$('productGrid').innerHTML=display.length?display.map(p=>{const v=p.variants.find(v=>v.enabled!==false),stock=p.variants.some(v=>DZ.stockAvailable(p.id,v.id)>0);return `<article class="product-card"><div class="product-image" data-art="${esc(p.art)}"><button class="product-open" data-action="product" data-id="${esc(p.id)}" aria-label="مشاهدهٔ ${esc(p.title)}">${art(p)}</button>${p.badge?`<span class="product-badge">${esc(p.badge)}</span>`:''}<button class="favorite-btn ${favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${esc(p.id)}" aria-label="علاقه‌مندی ${esc(p.title)}" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button></div><div class="product-details"><p class="product-category">${esc(categoryName(p.category))}${!stock?' · ناموجود':''}</p><button class="product-title" data-action="product" data-id="${esc(p.id)}">${esc(p.title)}</button><div class="product-bottom"><span class="product-price">${money(basePrice(p))}</span><div class="color-swatches" aria-label="رنگ‌های موجود">${p.category!=='digital'?p.variants.filter(v=>v.enabled!==false).slice(0,5).map(v=>`<span class="color-dot" style="--swatch:${/^#[\da-f]{3,8}$/i.test(v.color)?v.color:'#ddd'}" title="${esc(v.name)}"></span>`).join(''):'<span class="small muted" style="font-size:9px">انتخاب مدت</span>'}</div></div></div></article>`}).join(''):`<div class="empty-state" style="grid-column:1/-1">${icon('search')}<h3>هنوز انتخابی اینجا نیست.</h3><p>${DZ.state.loading?'در حال دریافت محصولات…':!DZ.state.configured?'فروشگاه هنوز آمادهٔ خرید نیست.':'دسته‌بندی یا عبارت جست‌وجو را تغییر بده؛ ممکن است هنوز محصولی منتشر نشده باشد.'}</p><button class="btn btn-light" data-action="reset-filters">دیدن همهٔ محصولات</button></div>`}
