function renderRuntime(){
 const el=$('runtimeStatus'),s=DZ.state;el.hidden=Boolean(s.configured&&!s.loading);
 if(s.loading){el.className='runtime-status';el.textContent='در حال دریافت اطلاعات فروشگاه…';}
 else if(!s.configured){el.className='runtime-status error';el.innerHTML=esc(s.error||s.message||'فروشگاه هنوز راه‌اندازی نشده است.')+' <a href="install.php">راهنمای نصب برای مدیر</a>';}
}
