function paymentMethodName(method){return ({zarinpal:'پرداخت آنلاین',digipay:'دیجی‌پی · اعتباری / قسطی',bank_transfer:'کارت‌به‌کارت / واریز بانکی',card:'کارت‌خوان',cash:'نقدی'})[method]||'پرداخت سفارش'}
function availablePaymentMethods(){return (DZ.state.paymentMethods||[]).filter(method=>method.available);}
function paymentChoices(){return `<fieldset class="payment-methods"><legend>روش پرداخت</legend>${availablePaymentMethods().map((method,i)=>`<label class="payment-option"><input type="radio" name="paymentMethod" value="${esc(method.id)}" ${i===0?'checked':''} required><span><strong>${esc(method.label||paymentMethodName(method.id))}</strong><small>${method.id==='digipay'?'روش‌های قابل استفاده و شرایط اعتبار در دیجی‌پی مشخص می‌شوند.':method.id==='bank_transfer'?'مشخصات حساب را می‌بینی؛ تأیید واریز توسط فروشگاه انجام می‌شود.':'پرداخت امن از طریق درگاه بانکی'}</small></span>${icon(method.id==='bank_transfer'?'shield':'arrow')}</label>`).join('')}</fieldset>`;}
async function beginCheckout(){if(DZ.cartIssues().length)return toast('اقلام غیرفعال را از سبد حذف کنید.','error');if(DZ.state.reservation?.status==='payment_pending'&&DZ.state.reservation.orderId){await resumePayment(DZ.state.reservation.orderId);return;}if(!availablePaymentMethods().length)return toast('روش پرداخت فعالی وجود ندارد. با پشتیبانی فروشگاه تماس بگیرید.','error');if(!DZ.cartCount())return toast('سبد خرید خالی است.','error');if($('cartDialog').open)$('cartDialog').close();if(!DZ.state.currentUser){loginModal('checkout');return}try{await DZ.reserveCart()}catch(e){toast(e.message,'error');return}const lines=DZ.cartLines(),physical=lines.some(l=>l.product.category!=='digital'),digital=lines.some(l=>l.product.category==='digital'),shipping=DZ.state.shipping.filter(s=>s.enabled!==false);if(physical&&!shipping.length){DZ.releaseReservation().catch(err=>toast(err.message,'error'));return toast('روش ارسال فعالی وجود ندارد؛ با پشتیبانی تماس بگیر.','error')}const user=DZ.state.currentUser;openModal(`<h2 class="modal-title">آخرین قدم برای انتخاب تو.</h2><p class="modal-subtitle">${physical?'اطلاعات گیرنده و روش ارسال را تکمیل کن.':'اطلاعات اشتراک دیجیتال را تکمیل کن.'}</p><form id="checkoutForm"><div class="form-grid"><label class="field"><span>نام و نام خانوادگی</span><input class="input" name="name" autocomplete="name" required value="${esc(user.name&&user.name!=='مشتری'&&user.name!=='مشتری جدید'?user.name:'')}"></label><label class="field"><span>شماره موبایل</span><input class="input" name="phone" dir="ltr" type="tel" required value="${esc(user.phone)}"></label></div>${physical?`<div class="form-grid"><label class="field"><span>استان</span><input class="input" name="province" autocomplete="address-level1" required placeholder="مثلاً تهران"></label><label class="field"><span>شهر</span><input class="input" name="city" autocomplete="address-level2" required></label></div><label class="field"><span>آدرس کامل</span><textarea name="address" autocomplete="street-address" required placeholder="خیابان، کوچه، پلاک و واحد"></textarea></label><label class="field"><span>کد پستی ده‌رقمی</span><input class="input" name="postalCode" dir="ltr" inputmode="numeric" required maxlength="10"></label><span class="small">روش ارسال</span><div class="checkout-shipping">${shipping.map((s,i)=>`<label class="shipping-option"><input type="radio" name="shippingId" value="${esc(s.id)}" ${i===0?'checked':''} required><span>${esc(s.name)}<small>${esc(s.description||'')}</small></span><b>${s.payOnDelivery?'کرایه در محل':money(s.fee)}</b></label>`).join('')}</div>`:''}${digital?`<label class="field" style="margin-top:18px"><span>نام کاربری تلگرام برای هماهنگی اشتراک</span><input class="input" name="telegram" dir="ltr" placeholder="@username" pattern="@?[A-Za-z][A-Za-z0-9_]{4,31}" required><small class="muted">رمز عبور و کد ورود حساب را وارد نکن.</small></label>`:''}${paymentChoices()}<div class="summary-box"><div class="summary-row"><span>مبلغ محصولات</span><strong>${money(DZ.cartTotal())}</strong></div><div class="summary-row"><span>ارسال</span><strong id="shippingTotal"></strong></div><div class="summary-row"><span>جمع نهایی</span><strong id="checkoutTotal"></strong></div></div><div class="demo-note" style="margin-top:16px">موجودی تا پایان این زمان برای پرداخت رزرو می‌شود: <strong id="reservationCountdown"></strong></div><div class="form-actions"><button class="btn btn-dark" type="submit" id="checkoutSubmit">ادامهٔ پرداخت${icon('check')}</button></div><p class="form-error" id="checkoutError" role="alert"></p></form>`);modalKind='checkout';updateCheckoutTotal();const tick=()=>{const remaining=Math.max(0,(Number(DZ.state.reservation?.expiresAt)||0)-Date.now());if($('reservationCountdown'))$('reservationCountdown').textContent=num(Math.floor(remaining/60000))+':'+String(Math.floor(remaining/1000)%60).padStart(2,'0');if(!remaining&&modalKind==='checkout'){closeModal();toast('زمان رزرو تمام شد؛ دوباره ادامهٔ خرید را انتخاب کن.','error')}};tick();checkoutTimer=setInterval(tick,1000)}
function bankDetailsHtml(details){
 const rows=[['صاحب حساب',details.holder],['بانک',details.bankName],['شماره کارت',details.card],['شماره شبا',details.iban]].filter(([,value])=>value);
 return `<div class="bank-details">${rows.map(([label,value])=>`<div class="bank-detail"><span>${label}</span><strong ${['شماره کارت','شماره شبا'].includes(label)?'dir="ltr"':''}>${esc(value)}</strong>${['شماره کارت','شماره شبا'].includes(label)?`<button type="button" class="btn-text payment-copy" data-action="copy-bank" data-value="${esc(value)}" aria-label="کپی ${label}">کپی</button>`:''}</div>`).join('')}</div>${details.instructions?`<p class="payment-instructions">${esc(details.instructions)}</p>`:''}`;
}
function manualPaymentModal(result){
 const order=DZ.state.orders.find(o=>o.id===result.orderId),details=result.manualPayment||order?.manualPayment;
 if(!details)throw Error('اطلاعات واریز در دسترس نیست؛ سفارش را از حساب کاربری پیگیری کنید.');
 const reviewStatus=details.reviewStatus||'awaiting_transfer';
 const submitted=reviewStatus==='pending_review',approved=reviewStatus==='approved'||order?.paymentStatus==='paid',closed=['rejected','cancelled'].includes(reviewStatus)||['cancelled','payment_failed'].includes(order?.status);
 openModal(`<p class="kicker">DEZHAWO / PAYMENT</p><h2 class="modal-title">${approved?'واریز تأیید شده است.':submitted?'واریزت در انتظار بررسی است.':'پرداخت با واریز بانکی'}</h2><p class="modal-subtitle">سفارش ${esc(result.number||order?.number||'')}</p>${order?`<div class="payment-amount"><span>${approved?'مبلغ سفارش':'مبلغ قابل پرداخت'}</span><strong>${money(order.total)}</strong></div>`:''}${bankDetailsHtml(details)}${submitted?'<p class="payment-notice" role="status">اطلاعات واریز ثبت شده است. پس از بررسی حساب بانکی توسط فروشگاه، نتیجه در سفارش نمایش داده می‌شود. ثبت رسید به معنی تأیید پرداخت نیست.</p>':''}${approved?'<p class="payment-notice" role="status">فروشگاه دریافت وجه این سفارش را تأیید کرده است.</p>':''}${closed?'<p class="payment-notice">این پرداخت بسته شده است. در صورت واریز وجه، از بخش پشتیبانی سفارش پیگیری کن.</p>':''}${details.reference?`<p class="small payment-reference">شماره پیگیری: <b dir="ltr">${esc(details.reference)}</b></p>`:''}${!submitted&&!approved&&!closed?`<p class="payment-notice">فقط پس از واریز مبلغ، شماره پیگیری بانکی را ثبت کن. سفارش تا بررسی فروشگاه پرداخت‌شده محسوب نمی‌شود؛ موجودی تا پایان مهلت رزرو نگه داشته می‌شود.</p><form id="transferForm"><input type="hidden" name="orderId" value="${esc(result.orderId)}"><label class="field"><span>شماره پیگیری واریز</span><input class="input" name="reference" dir="ltr" required maxlength="100" autocomplete="off" value="${esc(details.reference||'')}"></label><label class="field"><span>توضیح واریز (اختیاری)</span><textarea name="note" maxlength="1000" rows="3" placeholder="مثلاً زمان واریز و نام واریزکننده">${esc(details.note||'')}</textarea></label><div class="form-actions"><button class="btn btn-dark" type="submit">ثبت واریز برای بررسی${icon('check')}</button></div><p class="form-error" role="alert"></p></form>`:''}<div class="payment-modal-actions"><button type="button" class="btn-text" data-action="account-tab" data-tab="orders">سفارش‌های من${icon('arrow')}</button><button type="button" class="btn-text" data-action="ticket-new" data-order="${esc(result.orderId)}">پشتیبانی سفارش${icon('ticket')}</button></div>`);
}
function redirectPayment(result){
 modalKind='';clearInterval(checkoutTimer);checkoutTimer=null;
 if(result.manualPayment||result.paymentMethod==='bank_transfer'){manualPaymentModal(result);return;}
 if(!result.redirectUrl)throw Error('نشانی درگاه دریافت نشد؛ وضعیت سفارش را در حساب بررسی کنید.');
 const url=new URL(result.redirectUrl,location.href);if(url.protocol!=='https:'&&!(url.origin===location.origin&&url.protocol==='http:'))throw Error('نشانی درگاه معتبر نیست.');
 toast('در حال انتقال به درگاه پرداخت…');location.assign(url.href);
}
async function resumePayment(id){
 if(!DZ.state.currentUser){loginModal('account');return;}
 const order=DZ.state.orders.find(o=>o.id===id&&o.userId===DZ.state.currentUser.id);
 if(order&&(order.paymentMethod||order.payment)==='bank_transfer'&&order.manualPayment){manualPaymentModal({orderId:id,number:order.number,manualPayment:order.manualPayment,paymentMethod:'bank_transfer'});return;}
 redirectPayment(await DZ.resumeOrder(id));
}
function updateCheckoutTotal(){const f=$('checkoutForm');if(!f)return;const id=f.querySelector('input[name=shippingId]:checked')?.value,s=DZ.state.shipping.find(s=>s.id===id);const fee=s&&!s.payOnDelivery?Number(s.fee):0;$('shippingTotal').innerHTML=s?.payOnDelivery?'پرداخت کرایه هنگام تحویل':s?money(fee):'بدون ارسال';$('checkoutTotal').innerHTML=money(DZ.cartTotal()+fee);const submit=$('checkoutSubmit');if(submit)submit.innerHTML=(f.querySelector('input[name=paymentMethod]:checked')?.value==='bank_transfer'?'ثبت سفارش و مشاهدهٔ حساب':'ادامه در درگاه پرداخت')+icon('check')}
function accountModal(tab='orders'){if(!DZ.state.currentUser)return loginModal(tab==='tickets'?'support':'account');accountTab=tab;const u=DZ.state.currentUser;let html='';if(tab==='orders'){const orders=DZ.state.orders.filter(o=>o.userId===u.id);html=orders.length?orders.slice().map(o=>`<div class="order-card"><div class="summary-row"><h3>سفارش ${esc(o.number||o.code||o.id)}</h3><span class="pill">${esc(orderStatus(o.status))}</span></div><p class="small muted">${new Date(o.createdAt).toLocaleDateString('fa-IR',{timeZone:'Asia/Tehran'})}</p><div class="summary-row"><span>${num(o.lines?.reduce((n,l)=>n+(l.quantity||0),0)||0)} محصول</span><strong>${money(o.total||o.totalAmount||0)}</strong></div><p class="small muted">${o.type==='pos'?'فروش حضوری':o.shipping?.name||o.shippingName||'سفارش دیجیتال یا اینترنتی'}</p>${o.trackingCode?`<p class="small">کد رهگیری: <b dir="ltr">${esc(o.trackingCode)}</b></p>`:''}<p class="small muted">${esc(paymentMethodName(o.paymentMethod||o.payment))}</p>${o.paymentStatus==='pending_review'?'<p class="payment-status">واریز ثبت شده؛ در انتظار تأیید فروشگاه</p>':''}${o.paymentStatus==='refund_pending'?'<p class="payment-status">بازپرداخت در انتظار پیگیری فروشگاه است.</p>':''}${(o.paymentMethod||o.payment)==='bank_transfer'?`<button class="btn btn-light btn-small" data-action="resume-payment" data-id="${esc(o.id)}">${o.manualPayment?.reviewStatus==='awaiting_transfer'?'مشخصات حساب و ثبت واریز':'جزئیات واریز'}${icon('arrow')}</button>`:o.status==='awaiting_payment'?`<button class="btn btn-dark btn-small" data-action="resume-payment" data-id="${esc(o.id)}">ادامهٔ پرداخت${icon('arrow')}</button>`:''}<button class="btn-text" data-action="ticket-new" data-order="${esc(o.id)}">پشتیبانی این سفارش${icon('ticket')}</button></div>`).join(''):`<div class="empty-state">${icon('bag')}<h3>اولین انتخابت منتظر است.</h3><p>سفارش‌های تو اینجا نمایش داده می‌شوند.</p></div>`}else{const tickets=DZ.state.tickets.filter(t=>t.userId===u.id);html=`<button class="btn btn-dark btn-small" data-action="ticket-new">ثبت تیکت جدید${icon('plus')}</button>`+(tickets.length?tickets.slice().map(t=>`<div class="ticket-card"><div class="summary-row"><h3>${esc(t.subject)}</h3><span class="pill">${esc(ticketStatus(t.status))}</span></div><button class="btn-text" data-action="ticket-view" data-id="${esc(t.id)}">مشاهدهٔ گفتگو${icon('arrow')}</button></div>`).join(''):'<p class="empty-state">هنوز تیکتی ثبت نکرده‌ای.</p>')};openModal(`<p class="kicker" style="margin-bottom:10px">YOUR DEZHAWO</p><h2 class="modal-title">حساب من</h2><p class="small muted" dir="ltr" style="text-align:right">${esc(u.phone)}</p><div class="account-tabs"><button class="account-tab ${tab==='orders'?'active':''}" data-action="account-tab" data-tab="orders">سفارش‌های من</button><button class="account-tab ${tab==='tickets'?'active':''}" data-action="account-tab" data-tab="tickets">تیکت‌های من</button><button class="account-tab" data-action="logout">خروج${icon('logout')}</button></div>${u.permissions?.length?`<div class="form-actions" style="margin:0 0 20px"><button class="btn btn-dark" data-action="admin">پنل مدیریت${icon('grid')}</button></div>`:''}${html}`)}
function orderStatus(s){return ({awaiting_payment:'در انتظار پرداخت',awaiting_review:'در انتظار بررسی واریز',pending_review:'در انتظار تأیید واریز',paid:'پرداخت تأیید شده',payment_failed:'پرداخت ناموفق',payment_review:'نیازمند بررسی پرداخت',processing:'در حال آماده‌سازی',shipped:'ارسال شده',delivered:'تحویل شده',cancelled:'لغو شده',completed:'تکمیل شده',pending:'در انتظار بررسی'})[s]||s||'ثبت شده'}
function ticketStatus(s){return ({open:'باز',waiting:'در انتظار پاسخ مشتری',waiting_customer:'در انتظار پاسخ مشتری',closed:'بسته',answered:'پاسخ داده شده'})[s]||s}
function ticketNew(orderId=''){if(!DZ.state.currentUser){loginModal('ticket');return}openModal(`<h2 class="modal-title">چطور می‌توانیم کمک کنیم؟</h2><p class="modal-subtitle">پاسخ را در بخش تیکت‌های حساب کاربری می‌بینی.</p><form id="ticketForm"><input type="hidden" name="orderId" value="${esc(orderId)}"><label class="field"><span>موضوع</span><input class="input" name="subject" required maxlength="120" placeholder="مثلاً راهنمای انتخاب شارژر"></label><label class="field"><span>پیام تو</span><textarea name="message" required maxlength="3000" placeholder="سؤالت را با جزئیات بنویس…"></textarea></label><div class="form-actions"><button class="btn btn-dark" type="submit">ثبت تیکت${icon('arrow')}</button></div><p class="form-error" id="ticketError" role="alert"></p></form>`)}
function ticketView(id){const t=DZ.state.tickets.find(t=>t.id===id),u=DZ.state.currentUser;if(!t||!u||(t.userId!==u.id&&!DZ.can('tickets.view')))return toast('تیکت در دسترس نیست.','error');openModal(`<h2 class="modal-title">${esc(t.subject)}</h2><span class="pill">${esc(ticketStatus(t.status))}</span>${(t.messages||[]).map(m=>`<div class="ticket-message ${m.staff?'staff':''}"><small>${m.staff?'پشتیبانی دژاوو':'پیام شما'}</small>${esc(m.message||m.text)}</div>`).join('')}${t.status!=='closed'?`<form id="ticketReplyForm"><input name="ticketId" type="hidden" value="${esc(id)}"><label class="field"><span>پاسخ تو</span><textarea name="message" required maxlength="3000"></textarea></label><div class="form-actions"><button class="btn btn-dark" type="submit">ارسال پاسخ${icon('arrow')}</button></div><p class="form-error" id="ticketError" role="alert"></p></form>`:'<p class="small muted" style="margin-top:16px">این تیکت بسته شده است. برای موضوع تازه تیکت جدید ثبت کن.</p>'}`)}
function menuClose(){$('header').dataset.open='false';$('menuBtn').setAttribute('aria-expanded','false')}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b){if(!$('header').contains(e.target))menuClose();return}if(b.dataset.busy)return;const a=b.dataset.action;b.dataset.busy='1';const wasDisabled=b.disabled;if(b.tagName==='BUTTON')b.disabled=true;try{switch(a){case'menu':{const open=$('header').dataset.open!=='true';$('header').dataset.open=String(open);$('menuBtn').setAttribute('aria-expanded',String(open));if(open&&e.detail===0)$('mainLinks').querySelector('a,button')?.focus();break}case'admin':go('admin');break;case'store':go('store');break;case'search':$('catalogSearchBox').hidden=false;$('catalog').scrollIntoView({behavior:'smooth'});$('catalogSearch').focus({preventScroll:true});break;case'clear-search':query='';$('catalogSearch').value='';$('catalogSearchBox').hidden=true;renderCatalog();break;case'filter':setFilter(b.dataset.category);break;case'more':showAll=true;renderCatalog();break;case'reset-filters':category='all';query='';favoritesOnly=false;$('catalogSearch').value='';renderCatalog();break;case'favorites':favoritesOnly=true;category='all';showAll=true;query='';renderCatalog();$('catalog').scrollIntoView({behavior:'smooth'});break;case'favorite':favorites=favorites.includes(b.dataset.id)?favorites.filter(x=>x!==b.dataset.id):[...favorites,b.dataset.id];try{localStorage.setItem('dezhawo-favorites',JSON.stringify(favorites))}catch{}renderCatalog();toast(favorites.includes(b.dataset.id)?'به انتخاب‌های محبوبت اضافه شد.':'از علاقه‌مندی‌ها حذف شد.');break;case'product':productQuantity=1;productModal(b.dataset.id);break;case'variant':productQuantity=1;productModal(selectedProduct,b.dataset.variant);break;case'product-plus':{const available=DZ.stockAvailable(selectedProduct,selectedVariant);if(productQuantity<available){productQuantity++;$('productQuantity').textContent=num(productQuantity)}else toast('بیش از موجودی نمی‌توانی انتخاب کنی.','error');break}case'product-minus':if(productQuantity>1){productQuantity--;$('productQuantity').textContent=num(productQuantity)}break;case'add-cart':if(DZ.state.reservation?.status==='payment_pending')throw Error('پرداخت سفارش قبلی هنوز باز است؛ ابتدا آن را تکمیل کن یا تا پایان رزرو صبر کن.');await DZ.addCart(selectedProduct,selectedVariant,productQuantity);closeModal();toast('انتخابت به سبد اضافه شد.');openCart();break;case'cart':openCart();break;case'close-cart':$('cartDialog').close();break;case'cart-plus':case'cart-minus':case'cart-remove':{if(DZ.state.reservation?.status==='payment_pending')throw Error('در زمان پرداخت باز، تغییر سبد ممکن نیست.');const line=DZ.state.cart.find(l=>l.productId===b.dataset.product&&l.variantId===b.dataset.variant);if(line)await DZ.setCartQty(line.productId,line.variantId,a==='cart-remove'?0:line.quantity+(a==='cart-plus'?1:-1));break}case'shop':$('cartDialog').close();$('catalog').scrollIntoView({behavior:'smooth'});break;case'checkout':await beginCheckout();break;case'resume-payment':await resumePayment(b.dataset.id);break;case'copy-bank':{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(b.dataset.value||'');toast('اطلاعات حساب کپی شد.');}else toast('برای کپی، شماره حساب را انتخاب و نگه دار.');break;}case'close-modal':closeModal();break;case'account':accountModal();break;case'account-tab':accountModal(b.dataset.tab);break;case'change-phone':loginModal(loginPurpose);break;case'logout':await DZ.logout();closeModal();toast('از حساب خارج شدی.');break;case'support':accountModal('tickets');break;case'ticket-new':ticketNew(b.dataset.order||'');break;case'ticket-view':ticketView(b.dataset.id);break;case'digital':{const p=DZ.products().find(p=>p.category==='digital'&&p.enabled!==false);if(p){productQuantity=1;productModal(p.id)}else setFilter('digital');break}case'about':openModal(`<p class="kicker">THE DEZHAWO PHILOSOPHY</p><h2 class="modal-title" style="margin-top:15px">جزئیات کوچک، حال خوب هر روز.</h2><p class="product-description">دژاوو فروشگاه لوازم جانبی موبایل و اشتراک‌های دیجیتال برای بازار ایران است. فروشگاه حضوری و سایت از یک انبار مشترک استفاده می‌کنند تا انتخاب رنگ و موجودی هر محصول روشن باشد.</p><div class="summary-box">${esc(DZ.state.settings.address||'آدرس فروشگاه هنوز ثبت نشده است.')}</div><button class="btn btn-dark" style="margin-top:20px" data-action="support">ارتباط با دژاوو${icon('ticket')}</button>`);break;case'shipping-info':openModal(`<h2 class="modal-title">راه رسیدن سفارش تو.</h2><p class="modal-subtitle">روش‌های فعال ارسال فروشگاه</p>${DZ.state.shipping.filter(s=>s.enabled!==false).map(s=>`<div class="summary-box"><strong>${esc(s.name)}</strong><p class="small muted">${esc(s.description)}</p><p class="small" style="margin-top:8px">${s.payOnDelivery?'کرایه هنگام تحویل پرداخت می‌شود.':money(s.fee)}</p></div>`).join('')}`);break;case'policies':openModal('<h2 class="modal-title">راهنمای خرید</h2><p class="product-description">محصول و رنگ موردنظرت را انتخاب کن، وارد حساب شو و مشخصات سفارش را تکمیل کن. سفارش‌های فیزیکی به آدرس و روش ارسال نیاز دارند؛ اشتراک‌های دیجیتال جداگانه پیگیری می‌شوند.</p><div class="demo-note" style="margin-top:20px">برای اطلاع از شرایط ضمانت، مرجوعی و زمان فعال‌سازی هر محصول، توضیحات محصول را بخوانید یا از پشتیبانی بپرسید. هزینهٔ پس‌کرایه فقط مربوط به حمل است؛ مبلغ کالا هنگام خرید پرداخت می‌شود.</div>');break}}catch(err){toast(err.message||'عملیات انجام نشد.','error')}finally{delete b.dataset.busy;if(b.tagName==='BUTTON')b.disabled=wasDisabled;}});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['loginPhoneForm','loginCodeForm','checkoutForm','transferForm','ticketForm','ticketReplyForm'].includes(f.id))return;
 e.preventDefault();if(f.dataset.busy)return;f.dataset.busy='1';const submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;
 const d=Object.fromEntries(new FormData(f));const error=f.querySelector('.form-error');if(error)error.textContent='';
 try{
  if(f.id==='loginPhoneForm'){
   let p=normalizeDigits(d.phone).replace(/[\s()-]/g,'').replace(/^\+98/,'0').replace(/^0098/,'0');if(!/^09\d{9}$/.test(p))throw Error('شماره موبایل معتبر ایرانی وارد کن.');
   await DZ.requestOtp(p);loginPhone=p;codeModal();toast('کد ورود ارسال شد.');
  }else if(f.id==='loginCodeForm'){
   await DZ.verifyOtp(loginPhone,normalizeDigits(d.code));toast('به دژاوو خوش آمدی.');
   if(loginPurpose==='checkout')await beginCheckout();else if(loginPurpose==='ticket')ticketNew();else if(loginPurpose==='admin'&&DZ.state.currentUser?.permissions?.length)go('admin');else{accountModal(loginPurpose==='support'?'tickets':'orders');if(loginPurpose==='admin')toast('دسترسی پنل مدیریت برای این حساب فعال نیست.','error');}
  }else if(f.id==='checkoutForm'){
   const phone=normalizeDigits(d.phone).replace(/\s/g,'');if(!/^09\d{9}$/.test(phone))throw Error('شماره موبایل گیرنده معتبر نیست.');
   if(d.postalCode&&!/^\d{10}$/.test(normalizeDigits(d.postalCode)))throw Error('کد پستی باید ده رقم باشد.');if(!d.name.trim())throw Error('نام گیرنده را وارد کن.');
   const result=await DZ.checkout({customer:{name:d.name.trim(),phone,telegramUsername:d.telegram||''},address:d.address?{province:d.province,city:d.city,line:d.address,postalCode:normalizeDigits(d.postalCode)}:null,shippingId:d.shippingId||null,paymentMethod:d.paymentMethod});
   redirectPayment(result);
  }else if(f.id==='transferForm'){
   await DZ.submitTransfer(d.orderId,String(d.reference||'').trim(),String(d.note||'').trim());
   const order=DZ.state.orders.find(o=>o.id===d.orderId);
   if(order?.manualPayment)manualPaymentModal({orderId:order.id,number:order.number,manualPayment:order.manualPayment});else accountModal();
   toast('اطلاعات واریز ثبت شد؛ تأیید پرداخت پس از بررسی فروشگاه انجام می‌شود.');
  }else if(f.id==='ticketForm'){
   await DZ.createTicket(d.subject,d.message,d.orderId||null);accountModal('tickets');toast('تیکت ثبت شد.');
  }else if(f.id==='ticketReplyForm'){
   await DZ.replyTicket(d.ticketId,d.message);ticketView(d.ticketId);toast('پاسخت ثبت شد.');
  }
 }catch(err){if(error)error.textContent=err.message;else toast(err.message,'error');}
 finally{delete f.dataset.busy;if(submit)submit.disabled=false;}
});
$('catalogSearch').addEventListener('input',e=>{query=e.target.value.trim();showAll=true;renderCatalog()});$('catalogSort').addEventListener('change',e=>{sort=e.target.value;renderCatalog()});document.addEventListener('change',e=>{if(['shippingId','paymentMethod'].includes(e.target.name))updateCheckoutTotal()});$('modalDialog').addEventListener('cancel',()=>{const release=modalKind==='checkout';modalKind='';clearInterval(checkoutTimer);if(release)DZ.releaseReservation().catch(err=>toast(err.message,'error'))});document.addEventListener('keydown',e=>{if(e.key==='Escape')menuClose()});$('mainLinks').addEventListener('click',e=>{if(e.target.closest('a,button'))menuClose()});
