hydrateIcons();renderMosaic();refresh();DZ.subscribe(refresh);DZ.ready.then(()=>{refresh();const params=new URLSearchParams(location.search);if(params.has('payment')){if(DZ.state.currentUser)accountModal();else toast('برای بررسی نتیجهٔ پرداخت وارد حساب کاربری شوید.','error');}});
